def wrap(text, width):
    """Greedy word wrap to width characters, keeping paragraphs apart with one blank line.

    Blank lines (empty or whitespace-only) separate paragraphs. Within a paragraph all
    whitespace collapses to single spaces. A word longer than width goes on its own line,
    unbroken; hyphenated words are never split. Raises ValueError when width < 1.
    """
    if width < 1:
        raise ValueError(f"width must be at least 1, not {width}")

    paragraphs = []
    current = []
    for line in text.splitlines():
        if line.strip():
            current.append(line)
        elif current:
            paragraphs.append(" ".join(" ".join(current).split()))
            current = []
    if current:
        paragraphs.append(" ".join(" ".join(current).split()))

    out = []
    for i, para in enumerate(paragraphs):
        if i:
            out.append("")
        line = ""
        for word in para.split(" "):
            if not line:
                line = word
            elif len(line) + 1 + len(word) <= width:
                line += " " + word
            else:
                out.append(line)
                line = word
        out.append(line)
    return "\n".join(out)

