import contextlib
import io
import unittest

from textkit.cli import main
from textkit.wrap import wrap


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class WrapTest(unittest.TestCase):
    def test_greedy_fill(self):
        self.assertEqual(wrap("aaa bbb ccc", 7), "aaa bbb\nccc")
        self.assertEqual(wrap("aaa bbb ccc", 11), "aaa bbb ccc")
        self.assertEqual(wrap("aaa bbb ccc", 3), "aaa\nbbb\nccc")

    def test_whitespace_collapses_inside_paragraph(self):
        self.assertEqual(wrap("a\n  b\t\tc   d", 40), "a b c d")

    def test_paragraphs_separated_by_one_blank_line(self):
        self.assertEqual(wrap("one two\n\n\n   \nthree", 40), "one two\n\nthree")

    def test_no_leading_or_trailing_blank_lines(self):
        self.assertEqual(wrap("\n\n  hi there \n\n", 40), "hi there")

    def test_empty_text(self):
        self.assertEqual(wrap("", 10), "")
        self.assertEqual(wrap(" \n \n", 10), "")

    def test_long_word_on_its_own_line_unbroken(self):
        self.assertEqual(wrap("a abcdefghij b", 4), "a\nabcdefghij\nb")
        self.assertEqual(wrap("abcdefghij", 3), "abcdefghij")

    def test_hyphenated_word_not_split(self):
        self.assertEqual(wrap("well-known fact", 6), "well-known\nfact")

    def test_width_below_one_raises(self):
        for width in [0, -1]:
            with self.subTest(width=width):
                with self.assertRaises(ValueError):
                    wrap("x", width)


class WrapCommandTest(unittest.TestCase):
    def test_prints_wrapped_text(self):
        self.assertEqual(run("wrap", "aaa bbb ccc", "--width", "7"), (0, "aaa bbb\nccc\n", ""))

    def test_default_width_is_40(self):
        text = "word " * 12  # 59 characters once joined
        code, out, err = run("wrap", text.strip())
        self.assertEqual(code, 0)
        self.assertEqual(out, "word word word word word word word word\nword word word word\n")
        self.assertEqual(err, "")

    def test_width_zero_exits_2(self):
        code, out, err = run("wrap", "x", "--width", "0")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error:"))

